#!/bin/sh
# KT_MT sweep on ktts (warm median of reps 2-6), waits for idle GPU
cd ~/strix-rt; D=/sys/class/drm/card1/device; G=$MODELS/kitten2/hf/cpp/model-tq2_1.gguf; V=$MODELS/kitten2/hf/cpp/default/voices.json
TXT="Hello from the Framework Desktop. This voice is generated by a ternary speech model."
busy() { pgrep -f "logs/r11/pfq|release/(pf_|npu_|tern_|q38|lfm)|npu/target/release|llama-bench|llama-cli|build-.*/bin/llama" >/dev/null; }
w=0; while busy && [ $w -lt ${MAXWAIT:-900} ]; do sleep 2; w=$((w+2)); done; echo "[waited ${w}s busy=$(busy && echo YES || echo no)]"
echo high | sudo tee $D/power_dpm_force_performance_level >/dev/null
for mt in 4 8 16; do echo "KT_MT=$mt"; KT_MT=$mt ./target/release/ktts $G $MODELS/kitten2/rt/decoder $V Bruno "$TXT" /tmp/mt.wav 6 2>&1 | grep "^rep [2-6]"; cmp /tmp/mt.wav.tokens.json logs/kt/rs_e2e.wav.tokens.json && echo tokens_identical; done
echo auto | sudo tee $D/power_dpm_force_performance_level >/dev/null; echo "[busy end=$(busy && echo YES || echo no)]"
